// Test data for standalone runs. The real caller is the main workflow's
// Accounts config. account_id = the Threads user id (the numeric id returned
// when the access token was created / by GET /me).
// channel decides WHICH credential is used: 'Brand A' -> "Threads Brand A",
// anything else -> "Threads Brand B".
return [
  { json: { platform: 'Threads', channel: 'Brand A', account_id: 'YOUR_THREADS_USER_ID_A', days: 14 } },
  { json: { platform: 'Threads', channel: 'Brand B', account_id: 'YOUR_THREADS_USER_ID_B', days: 14 } },
];

// Common landing point for both entry paths (the real "When Executed by
// Parent" caller and "Test manually"), so downstream nodes can reference ONE
// upstream node by name for account_id/channel.
return $input.all();

// Turns the posts responses into ONE item per eligible post, each carrying
// the post's own fields plus the account it belongs to. The next step then
// calls /{media-id}/insights per post.
//
// Accounts are matched by `owner.id` (requested in the posts call), not by
// item position, because the two account branches are merged back together.

const ctxs = $('Prepare request').all().map(i => i.json);
const byOwner = new Map(ctxs.map(c => [String(c.account_id), c]));

function parseTs(s) {
  if (!s) return NaN;
  // Threads returns "2024-01-01T10:00:00+0000" (offset without a colon).
  return new Date(String(s).replace(/([+-]\d{2})(\d{2})$/, '$1:$2')).getTime();
}

const out = [];

for (const item of $input.all()) {
  const res = item.json || {};
  const body = res.body || {};
  if (!Array.isArray(body.data)) continue; // API error: reported by the normalizer

  for (const p of body.data) {
    if (!p || !p.id) continue;
    if (p.media_type === 'REPOST_FACADE') continue; // someone else's post -- no insights, not ours

    const ctx = byOwner.get(String(p.owner && p.owner.id)) || (ctxs.length === 1 ? ctxs[0] : null);
    if (!ctx) continue;

    const days = Number(ctx.days) || 14;
    const ts = parseTs(p.timestamp);
    if (Number.isFinite(ts) && ts < Date.now() - days * 86400000) continue;

    out.push({
      json: {
        media_id: String(p.id),
        channel: ctx.channel,
        account_id: ctx.account_id,
        post: p,
      },
      pairedItem: 0,
    });
  }
}

if (!out.length) {
  // Marker so the workflow still reaches the normalizer (and can report
  // "no posts" / the API error) instead of ending silently.
  return [{ json: { _none: true, channel: ctxs[0] ? ctxs[0].channel : '' }, pairedItem: 0 }];
}

return out;

// Maps Threads API data into the standard row schema.
//   views    <- insights `views`
//   likes    <- insights `likes`
//   comments <- insights `replies`
//   shares   <- insights `reposts` + `quotes`
// Insights responses are matched to posts by media id (the response's
// data[].id is "<media_id>/insights/<metric>/lifetime"), never by position.
// A post whose insights call failed is still emitted (insights_ok: false,
// metrics null) so it isn't silently dropped.

const ctxs = $('Prepare request').all().map(i => i.json);

// --- insights by media id ---
const metricsById = new Map();
for (const item of $input.all()) {
  const body = (item.json && item.json.body) || {};
  if (!Array.isArray(body.data)) continue;
  for (const m of body.data) {
    if (!m || !m.id || !m.name) continue;
    const mediaId = String(m.id).split('/')[0];
    const v = m.values && m.values[0] ? m.values[0].value : (m.total_value ? m.total_value.value : null);
    if (!metricsById.has(mediaId)) metricsById.set(mediaId, {});
    metricsById.get(mediaId)[m.name] = typeof v === 'number' ? v : null;
  }
}

const posts = $('Build insights requests').all().map(i => i.json).filter(j => j.media_id);

// --- posts-call errors (for the "nothing returned" message) ---
let apiError = '';
for (const item of $('Merge posts').all()) {
  const r = item.json || {};
  if (r.statusCode >= 400 || (r.body && r.body.error)) {
    const e = (r.body && r.body.error) || {};
    apiError = `Threads API error ${r.statusCode || ''}: ${e.message || 'request failed'}`.trim();
  }
}

function parseIso(s) {
  if (!s) return null;
  const d = new Date(String(s).replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function postType(p) {
  if (p.is_quote_post) return 'Quote';
  switch (p.media_type) {
    case 'IMAGE': return 'Photo';
    case 'VIDEO': return 'Video';
    case 'CAROUSEL_ALBUM': return 'Carousel';
    case 'AUDIO': return 'Audio';
    default: return 'Text';
  }
}

const num = v => (typeof v === 'number' ? v : null);

const rows = posts.map(j => {
  const p = j.post;
  const m = metricsById.get(j.media_id);
  const ok = !!m && typeof m.views === 'number';
  const shares = m && (num(m.reposts) !== null || num(m.quotes) !== null)
    ? (m.reposts || 0) + (m.quotes || 0)
    : null;

  return {
    json: {
      platform: 'Threads',
      channel: j.channel,
      account_id: j.account_id,
      likes_label: 'Likes',
      id: j.media_id,
      title: String(p.text || '').replace(/\s+/g, ' ').trim().slice(0, 100),
      type: postType(p),
      views: ok ? m.views : null,
      likes: m ? num(m.likes) : null,
      comments: m ? num(m.replies) : null,
      shares,
      permalink: p.permalink || null,
      created_at: parseIso(p.timestamp),
      insights_ok: ok,
    },
    pairedItem: 0,
  };
});

// Accounts that returned no posts: one skipped row each (the report ignores them).
const withPosts = new Set(posts.map(j => String(j.account_id)));
for (const c of ctxs) {
  if (withPosts.has(String(c.account_id))) continue;
  rows.push({
    json: {
      platform: 'Threads',
      channel: c.channel,
      skipped: true,
      reason: apiError || `No Threads posts in the last ${Number(c.days) || 14} days.`,
    },
    pairedItem: 0,
  });
}

return rows;
